// Üretilen dosya: tool/ozgun/uret.py. Doğa · Bitkiler ve ormanlar; Türkiye'nin endemik türleri (kolay).
const ozNature2Kolay = <(String, String, List<String>, String)>[
  ('Bitki hücresini hayvan hücresinden ayıran ve hücreye dışarıdan şekil ve destek veren, büyük ölçüde selülozdan oluşan yapı hangisidir?', 'Hücre duvarı', ['Hücre zarı', 'Sentrozom', 'Lizozom zarı ve kesecikleri'], 'Bitki hücrelerinde hücre zarının dışında selülozdan yapılmış bir hücre duvarı bulunur; hayvan hücrelerinde bu yapı yoktur.'),
  ('Olgun bir bitki hücresinin hacminin büyük bölümünü kaplayabilen, su ve çözünmüş maddeleri depolayıp hücrenin turgor basıncını sağlayan organel hangisidir?', 'Merkezî koful', ['Golgi aygıtı', 'Ribozom', 'Çekirdekçik ve çekirdek zarı'], 'Bitki hücrelerindeki büyük merkezî koful su depolar; içindeki suyun hücre duvarına yaptığı baskı turgor basıncı olarak hücreyi dik tutar.'),
  ('Fotosentezin genel denkleminde karbondioksit ve suyun ışık enerjisiyle dönüştürülmesi sonucunda glikozun yanında açığa çıkan gaz hangisidir?', 'Oksijen', ['Azot', 'Metan', 'Hidrojen'], 'Fotosentezde 6CO2 + 6H2O ışık enerjisiyle C6H12O6 + 6O2\'ye dönüşür; açığa çıkan oksijen atmosfere verilir.'),
  ('Yaprakların çoğunlukla yeşil görünmesinin nedeni nedir?', 'Klorofil yeşil ışığı az soğurup büyük ölçüde yansıtır', ['Klorofil yalnızca yeşil ışığı soğurur', 'Yaprak hücreleri yeşil renkli bir sıvı taşır', 'Kloroplastlar karanlıkta kendiliğinden yeşil ışık üretir'], 'Klorofil en çok mavi ve kırmızı ışığı soğurur; yeşil dalga boylarını büyük ölçüde yansıttığı için göze yeşil görünür.'),
  ('Seralarda bazen ortam havasına ek karbondioksit verilir. Bu uygulamanın amacı nedir?', 'Fotosentez hızını ve ürün verimini artırmak', ['Zararlı böcekleri seradan uzaklaştırmak', 'Bitkilerin çiçek açmasını engellemek', 'Topraktaki suyun buharlaşmasını hızla artırmak'], 'Işık ve sıcaklık yeterliyken CO2 çoğu zaman sınırlayıcıdır; derişimin artırılması fotosentezi hızlandırarak verimi yükseltir.'),
  ('Bitkiler karbondioksiti dışarıdan almanın yanında kendi hücrelerinde de üretir. Bitki hücrelerinde karbondioksit üreten süreç hangisidir?', 'Hücresel solunum', ['Fotosentezin ışık evresi', 'Terleme', 'Ozmoz'], 'Bitkiler de gece ve gündüz hücresel solunum yaparak glikozu yıkar ve CO2 açığa çıkarır; fotosentez ise CO2 tüketir.'),
  ('Bitkilerin yapraklarındaki stomalardan su buharı kaybetmesine ne ad verilir?', 'Terleme (transpirasyon)', ['Damlama (gutasyon)', 'Soğurma (absorpsiyon)', 'Difüzyonla beslenme ve emilim'], 'Terleme, suyun yaprak hücrelerinden buharlaşıp stomalardan atmosfere geçmesidir ve su taşınmasının ana itici gücüdür.'),
  ('Rüzgârlı, sıcak ve kuru bir günde bir bitkinin terleme hızı, serin, nemli ve durgun bir güne göre nasıl değişir?', 'Artar', ['Azalır', 'Hiç değişmez', 'Sıfıra iner'], 'Sıcaklık ve rüzgâr buharlaşmayı hızlandırır, kuru hava ise yaprak ile çevre arasındaki nem farkını büyütür; bu yüzden terleme artar.'),
  ('Bitkilerde fotosentezle üretilen şekerlerin yapraklardan meyve, kök ve diğer organlara taşınmasını sağlayan iletim dokusu hangisidir?', 'Floem', ['Ksilem', 'Epidermis', 'Kambiyum'], 'Floem (soymuk borusu) organik maddeleri, özellikle sakarozu, üretildikleri yerden kullanıldıkları ya da depolandıkları yere taşır.'),
  ('Bitkilerde sürekli bölünebilen ve boyca uzamayı sağlayan, kök ve gövde uçlarında bulunan doku hangisidir?', 'Uç meristem', ['Yan meristem', 'Mantar dokusu', 'Destek dokusu'], 'Uç (apikal) meristemler kök ve sürgün uçlarında bulunur ve bölünerek bitkinin boyca uzamasını sağlar.'),
  ('Köklerde su ve mineral emilimini büyük ölçüde artıran, epidermis hücrelerinin ince uzantıları olan yapılar hangileridir?', 'Kök tüyleri', ['Lentiseller', 'Rizoitler', 'Stomalar ve hidatotlar'], 'Kök tüyleri tek hücreli uzantılardır ve emici yüzeyi çok büyütür; fide şaşırtılırken bu tüylerin zarar görmesi bitkinin solmasına yol açabilir.'),
  ('Havuç, turp ve pancarda kalınlaşarak besin depolayan ana kök hangi kök tipine örnektir?', 'Kazık kök', ['Saçak kök', 'Tutunma kökü', 'Solunum kökü'], 'Bu bitkilerde toprağa dik inen ana kök belirgindir ve besin depolayarak kalınlaşır; bu yapı kazık köktür.'),
  ('Kaktüslerde fotosentezi büyük ölçüde hangi organ üstlenir?', 'Etli yeşil gövde', ['Dikenler', 'Toprak altındaki kökler', 'Çiçek yaprakları'], 'Kaktüslerde yapraklar dikene dönüşmüştür; su depolayan etli yeşil gövde fotosentezin ana yeridir.'),
  ('Stomaların açılıp kapanmasını, şişip büzülerek denetleyen fasulye biçimli hücrelere ne ad verilir?', 'Bekçi hücreleri', ['Arkadaş hücreleri', 'Kalburlu boru hücreleri', 'Palizat parankima hücreleri'], 'Her stomanın iki yanında bulunan bekçi hücreleri su alıp şişince stoma açılır, su kaybedince kapanır.'),
  ('Yaprak epidermisinin üzerini örten ve su kaybını azaltan mumsu tabaka hangisidir?', 'Kütikula', ['Kambiyum', 'Mezofil', 'Endodermis'], 'Kütikula kutin adlı mumsu bir maddeden oluşur; kurak bölge bitkilerinde genellikle daha kalındır.'),
  ('Bir yaprağın sapı üzerinde birden çok küçük yaprakçık bulunuyorsa, örneğin gülde ya da cevizde olduğu gibi, bu yaprak nasıl sınıflandırılır?', 'Bileşik yaprak', ['Basit yaprak', 'Pul yaprak', 'Brakte ya da çiçek yaprağı'], 'Bileşik yaprakta yaprak ayası ayrı yaprakçıklara bölünmüştür; tomurcuk yaprakçığın değil yaprak sapının dibinde bulunur.'),
  ('Bir öğrenci elindeki bitkinin yapraklarında damarların birbirine paralel uzandığını görüyor. Bu bitkinin en büyük olasılıkla hangi gruba ait olduğu söylenebilir?', 'Tek çenekliler', ['Çift çenekliler', 'Açık tohumlular', 'Eğreltiler'], 'Paralel damarlanma tek çenekli bitkilerin tipik özelliğidir; çift çeneklilerde ise genellikle ağsı damarlanma görülür.'),
  ('Bir çiçekte en dışta yer alan, genellikle yeşil olup tomurcuk dönemindeki çiçeği koruyan yapraklara ne ad verilir?', 'Çanak yapraklar', ['Taç yapraklar', 'Başçıklar', 'Tepecikler ve dişicik boruları'], 'Çanak yaprakların (sepal) bütününe kaliks denir; tomurcuğu dıştan sararak korur.'),
  ('Erkek organda polenlerin üretildiği, sapın ucundaki kese biçimli kısım hangisidir?', 'Başçık (anter)', ['Tepecik', 'Yumurtalık', 'Dişicik borusu (stilus)'], 'Erkek organ (stamen) ince bir sap (filament) ve onun ucundaki başçıktan oluşur; polenler başçıkta gelişir.'),
  ('Dişi organın en üst kısmında yer alan ve polenleri yakalayıp tutmaya elverişli, çoğu zaman yapışkan yüzeyli bölüm hangisidir?', 'Tepecik', ['Başçık', 'Çanak yaprak', 'Sap'], 'Tepecik (stigma) polen tanelerini tutar; buradan çimlenen polen tüpü dişicik borusu boyunca yumurtalığa iner.'),
  ('Hem erkek hem dişi organ taşıyan çiçeklere ne ad verilir?', 'Erselik çiçek', ['Tek eşeyli çiçek', 'Kısır çiçek', 'Bileşik çiçek'], 'Erkek ve dişi organı aynı çiçekte bulunduran çiçeklere erselik (hermafrodit) çiçek denir; elma ve gül çiçekleri buna örnektir.'),
  ('Polenin bir çiçeğin başçığından aynı türden bir çiçeğin tepeciğine taşınmasına ne ad verilir?', 'Tozlaşma', ['Döllenme', 'Çimlenme', 'Tomurcuklanma'], 'Tozlaşma polenin tepeciğe ulaşmasıdır; döllenme ise bunun ardından sperm ile yumurtanın birleşmesidir.'),
  ('Döllenmeden sonra çiçekteki yumurtalık ve tohum taslağı neye dönüşür?', 'Yumurtalık meyveye, taslak tohuma', ['Yumurtalık tohuma, taslak meyveye', 'İkisi birlikte köke', 'Yumurtalık yaprağa, taslak ise çiçek sapına'], 'Döllenmeden sonra tohum taslakları tohuma, onları içeren yumurtalık ise meyveye dönüşür.'),
  ('Tohumun içindeki embriyoya ilk besini sağlayan ve fasulyede iki tane olan tohum yapraklarına ne ad verilir?', 'Kotiledon', ['Kaliptra', 'Brakte', 'Stolon ya da sürünücü gövde'], 'Kotiledonlar embriyonun ilk yapraklarıdır; fasulye gibi çift çeneklilerde iki, buğday gibi tek çeneklilerde tek çenek bulunur.'),
  ('Mutfakta sebze sayılan aşağıdakilerden hangisi botanik açıdan bir meyvedir?', 'Domates', ['Ispanak', 'Havuç', 'Pırasa sapı'], 'Botanikte meyve, çiçeğin yumurtalığından gelişen ve tohum taşıyan yapıdır; domates bu tanıma uyar. Ispanak yaprak, havuç kök, pırasa yaprak kınlarıdır.'),
  ('Karahindibanın tohumları paraşüt benzeri tüyleri sayesinde uzaklara taşınır. Bu yayılma yolu hangisidir?', 'Rüzgârla yayılma', ['Hayvanla yayılma', 'Suyla yayılma', 'Patlayarak yayılma'], 'Karahindiba meyvelerindeki tüy demeti (papus) havada süzülmeyi sağlar ve tohumlar rüzgârla kilometrelerce taşınabilir.'),
  ('Hindistan cevizinin okyanus adalarına bile yayılabilmesini sağlayan özelliği nedir?', 'Lifli kabuğu sayesinde suda yüzebilmesi', ['Tohumlarının rüzgârla havalanması', 'Kuşların meyveyi taşıması', 'Köklerinin denizin dibinde adalara kadar uzanması'], 'Hindistan cevizinin hava içeren lifli kabuğu onu yüzdürür ve tuzlu suya karşı korur; böylece akıntılarla adalar arasında taşınabilir.'),
  ('Etli ve renkli meyvelerin kuşlarca yenmesi bitkiye nasıl bir yarar sağlar?', 'Tohumlar dışkıyla uzağa bırakılır', ['Meyvenin olgunlaşması hızlanır', 'Bitki böceklerden korunur', 'Çiçeklerin açması bir sonraki yıla kadar gecikir'], 'Kuşlar meyvenin etli kısmını sindirir, sert kabuklu tohumları ise dışkıyla başka yerlere bırakır; böylece bitki yeni alanlara yayılır.'),
  ('Bir tohumun çimlenebilmesi için genellikle gerekli olan üç temel çevre koşulu hangisinde doğru verilmiştir?', 'Su, uygun sıcaklık ve oksijen', ['Işık, toprak ve gübre', 'Su, ışık ve karbondioksit', 'Toprak, rüzgâr ve yüksek sıcaklık'], 'Çimlenme için tohumun su alması, enzimlerin çalışacağı sıcaklık ve solunum için oksijen gerekir. Çoğu tohum için ışık ve toprak zorunlu değildir.'),
  ('Bitkilerin ışığa doğru yönelmesini, hücrelerin gölgede kalan tarafta daha çok uzamasıyla sağlayan hormon hangisidir?', 'Oksin', ['Etilen', 'Absisik asit', 'Sitokinin'], 'Oksin gölge tarafta birikir ve o taraftaki hücrelerin daha çok uzamasına yol açar; gövde böylece ışığa doğru eğilir.'),
  ('Olgunlaşmamış muzlar olgun elmalarla aynı kapalı torbaya konduğunda daha çabuk olgunlaşır. Bunu sağlayan gaz hâlindeki hormon hangisidir?', 'Etilen', ['Giberellin', 'Oksin', 'Sitokinin'], 'Olgun meyveler etilen gazı yayar; etilen çevredeki meyvelerde de olgunlaşmayı başlatır ve hızlandırır.'),
  ('Yatay olarak yere bırakılan bir fidenin kökünün aşağıya, gövdesinin yukarıya doğru kıvrılması hangi uyartıya verilen tepkidir?', 'Yerçekimi', ['Işık', 'Dokunma', 'Kimyasal madde'], 'Bu yönelime gravitropizma (geotropizma) denir; kök pozitif, gövde negatif gravitropizma gösterir.'),
  ('Pencere önünde duran bir saksı bitkisinin gövdesi zamanla cama doğru eğilmiştir. Bitkinin her tarafının dengeli büyümesi için en uygun uygulama hangisidir?', 'Saksıyı düzenli aralıklarla döndürmek', ['Bitkiyi daha sık sulamak', 'Saksıya daha çok gübre koymak', 'Yaprakların cama yakın olan kısmını koparmak'], 'Gövde fototropizmayla ışığa yönelir; saksı döndürülünce ışık farklı yönlerden gelir ve eğilme dengelenir.'),
  ('Ticari gübrelerin üzerinde yazan N-P-K harfleri hangi üç temel besin elementini gösterir?', 'Azot, fosfor, potasyum', ['Neon, platin, kripton', 'Nikel, fosfor, kalsiyum', 'Azot, kurşun, karbon'], 'N azotu, P fosforu, K potasyumu simgeler; bunlar bitkilerin en çok gereksinim duyduğu makro besin elementleridir.'),
  ('Eğrelti otlarının yapraklarının alt yüzeyinde görülen kahverengi nokta kümelerinin içinde ne bulunur?', 'Spor keseleri', ['Tohumlar', 'Polen keseleri', 'Böcek yumurtaları'], 'Bu kümeler sorus adını alır ve içlerinde sporangiumlar bulunur; buralarda oluşan sporlar rüzgârla dağılır.'),
  ('Açık tohumlu bitkilere bu adın verilmesinin nedeni nedir?', 'Tohumların bir meyve içinde olmayıp açıkta bulunması', ['Çiçeklerinin her zaman açık kalması', 'Tohumlarının kabuksuz olması', 'Yalnızca ağaçsız ve açık arazide yetişebilmeleri'], 'Açık tohumlularda tohum taslakları kozalak pulları gibi yapıların üzerinde açıkta durur; yumurtalık içine kapanmaz.'),
  ('Aşağıdaki bitkilerden hangisi açık tohumludur?', 'Ardıç', ['Meşe', 'Ceviz', 'Kiraz ağacı'], 'Ardıç bir kozalaklıdır; meyveye benzeyen etli kozalağına rağmen tohumları yumurtalık içinde gelişmez. Diğerleri kapalı tohumludur.'),
  ('Çam ağacında erkek kozalaklarda üretilen polenin yumurta hücresine ulaşmasında başlıca taşıyıcı nedir?', 'Rüzgâr', ['Arılar', 'Kuşlar', 'Yağmur suyu'], 'Kozalaklılarda tozlaşma rüzgârla olur; çam polenlerinin iki küçük hava kesesi havada uzun süre kalmalarını sağlar.'),
  ('Aşağıdaki bitkilerin hangisi tek çeneklidir?', 'Lale', ['Fasulye', 'Gül', 'Ayçiçeği'], 'Lale zambakgillere yakın bir tek çeneklidir: paralel damarlı yaprakları ve üçün katı çiçek parçaları vardır. Diğerleri çift çeneklidir.'),
  ('Nane, kekik, adaçayı ve lavantanın ortak özellikleri olan dört köşeli gövde, karşılıklı yapraklar ve güçlü koku hangi familyayı tanıtır?', 'Ballıbabagiller', ['Gülgiller', 'Patlıcangiller', 'Baklagiller ve akrabaları'], 'Ballıbabagiller (Lamiaceae) dört köşeli gövdeleri, karşılıklı dizilmiş yaprakları ve uçucu yağ salgılayan tüyleriyle tanınır.'),
  ('Elma, armut, kiraz, kayısı, çilek ve kuşburnu aynı familyanın üyeleridir. Bu familya hangisidir?', 'Gülgiller', ['Turunçgiller', 'Kabakgiller', 'Maydanozgiller'], 'Gülgiller (Rosaceae) meyveciliğin en önemli familyasıdır; sert çekirdekli, yalancı ve toplu meyve tipleri bu familyada görülür.'),
  ('Domates, patates, biber, patlıcan ve tütün aynı familyadandır. Bu familyanın adı nedir?', 'Patlıcangiller', ['Kabakgiller', 'Ballıbabagiller', 'Gülgiller ve akrabaları'], 'Patlıcangiller (Solanaceae) çoğu Amerika kökenli önemli kültür bitkilerini ve güzelavratotu gibi zehirli türleri içerir.'),
  ('Fasulye, nohut, mercimek ve bezelyenin ortak özelliği olan, iki kenarından açılan uzun kuru meyve tipinin adı nedir?', 'Bakla', ['Kapsül', 'Üzümsü meyve', 'Kanatlı meyve'], 'Baklagillerin meyvesi tek karpelden gelişen ve iki dikiş boyunca açılan baklalardır.'),
  ('Buğday, arpa, mısır, pirinç ve bambunun ortak olarak dahil olduğu familya hangisidir?', 'Buğdaygiller', ['Zambakgiller', 'Turpgiller', 'Baklagiller familyası'], 'Buğdaygiller (Poaceae) dünyanın tahıllarının neredeyse tamamını sağlar; bambular da bu familyanın odunsu üyeleridir.'),
  ('Limon, portakal, mandalina ve greyfurdun dahil olduğu familya hangisidir?', 'Turunçgiller', ['Gülgiller', 'Patlıcangiller', 'Kabakgiller familyası'], 'Turunçgiller (Rutaceae) yapraklarında ve kabuklarında uçucu yağ bezleri taşır; bu nedenle limon kabuğu kokuludur.'),
  ('Afyon ilinin adı, bölgede eskiden beri yetiştirilen ve olgunlaşmamış kapsüllerinden süt benzeri bir öz elde edilen bitkiden gelir. Bu bitki hangisidir?', 'Haşhaş', ['Gelincik', 'Ayçiçeği', 'Kenevir'], 'Haşhaşın (Papaver somniferum) çizilen kapsüllerinden sızan sütten afyon elde edilir; morfin gibi ağrı kesicilerin kaynağıdır. Türkiye\'de ekimi devlet denetimindedir.'),
  ('Doğu Karadeniz\'de bazı ormangülü türlerinin nektarından yapılan bal, fazla tüketildiğinde baş dönmesi ve tansiyon düşüklüğüne yol açabilir. Halk arasında bu bala ne ad verilir?', 'Deli bal', ['Çam balı', 'Kestane balı', 'Kekik balı'], 'Rhododendron ponticum ve akrabalarının nektarındaki grayanotoksinler bala geçer; bu bal \'deli bal\' olarak bilinir ve aşırısı zehirlenmeye yol açar.'),
  ('Bir meyve bahçesinde istenen çeşidin dalı, köklü bir başka ağacın gövdesine yerleştirilip kaynaştırılıyor. Bu yönteme ne ad verilir?', 'Aşılama', ['Çelikle çoğaltma', 'Daldırma', 'Tohumla üretim yapma'], 'Aşılamada üstteki aşı kalemi istenen meyve özelliklerini, alttaki anaç ise kök sistemini ve dayanıklılığı sağlar.'),
  ('Söğüt dallarının nemli toprağa ya da suya konduğunda kolayca kök vermesinden yararlanan çoğaltma yöntemi hangisidir?', 'Çelikle çoğaltma', ['Aşılama', 'Tohumla çoğaltma', 'Sporla çoğaltma ve bölme'], 'Çelikle çoğaltmada bitkiden kesilen dal parçaları köklendirilir; söğüt ve kavak bu yönteme çok yatkındır.'),
  ('Tropikal ormanlarda ağaç dallarının üzerinde yaşayan ama konağından besin almayan orkide gibi bitkilere ne ad verilir?', 'Epifit', ['Parazit', 'Saprofit', 'Halofit'], 'Epifitler başka bitkileri yalnızca tutunmak ve ışığa ulaşmak için kullanır; suyu yağmurdan ve havadaki nemden, mineralleri birikmiş organik artıklardan alır.'),
  ('Tuzlu topraklarda yaşayabilen bitkilere genel olarak ne ad verilir?', 'Halofit', ['Hidrofit', 'Epifit', 'Mezofit'], 'Halofitler tuzu yapraklardaki bezlerle dışarı atma, kofullarda biriktirme ya da etli dokularda seyreltme gibi yollarla tuzlu ortama uyum sağlar.'),
  ('Akdeniz ve Ege kıyılarının alçak kesimlerinde en yaygın çam türü olan, Türkçe adı gövdesinin kızılımsı kabuğundan gelen ağaç hangisidir?', 'Kızılçam (Pinus brutia)', ['Sarıçam (Pinus sylvestris)', 'Fıstık çamı (Pinus pinea)', 'Karaçam (Pinus nigra)'], 'Kızılçam Türkiye\'nin kıyı kuşağında deniz seviyesinden yaklaşık 1000 metreye kadar geniş ormanlar oluşturur.'),
  ('Tepesi şemsiye biçiminde yayılan, iri kozalaklarından yenebilen çam fıstığı elde edilen ve Bergama\'daki Kozak Yaylası\'nda yaygın olan ağaç hangisidir?', 'Fıstık çamı', ['Karaçam', 'Sarıçam', 'Halep çamı ya da Kıbrıs çamı'], 'Fıstık çamının (Pinus pinea) tohumları büyük ve yenilebilir; Kozak Yaylası Türkiye\'nin önemli çam fıstığı üretim alanlarındandır.'),
  ('Mezarlık ve bahçelerde dik, sütun biçimli görünümüyle tanınan ve Akdeniz havzasının simge ağaçlarından olan iğne-pul yapraklı ağaç hangisidir?', 'Adi servi (Cupressus sempervirens)', ['Sarıçam (Pinus sylvestris)', 'Doğu ladini (Picea orientalis)', 'Avrupa melezi (Larix decidua)'], 'Servinin pul biçimli küçük yaprakları ve dar, sivri tepe yapısı vardır; Türk ve Akdeniz kültürlerinde mezarlıklarda geleneksel olarak dikilir.'),
  ('Meşe ağaçlarının meyvesine verilen ad hangisidir?', 'Palamut', ['Kozalak', 'Kestane kabuğu', 'Kanatlı tohum'], 'Meşelerin meyvesi tabanı kadeh biçiminde bir kupulayla sarılı olan palamuttur; birçok yaban hayvanı için önemli besindir.'),
  ('Anadolu\'nun akarsu kenarlarında ve köy meydanlarında yetişen, el biçimli yaprakları ve yaşlandıkça plakalar hâlinde dökülen kabuğuyla tanınan uzun ömürlü ağaç hangisidir?', 'Doğu çınarı', ['Kızılağaç', 'Ak kavak', 'Ihlamur ya da dişbudak'], 'Doğu çınarı (Platanus orientalis) yüzlerce yıl yaşayabilir; geniş gölgesi nedeniyle Anadolu\'da köy ve cami avlularında sıkça bulunur.'),
  ('Kavak ağaçlarının Türkiye\'de kâğıt, kibrit ve kontrplak sanayinde yaygın kullanılmasının en önemli nedeni nedir?', 'Çok hızlı büyüyüp kısa sürede odun vermesi', ['Odununun hiç yanmaması', 'Yapraklarını hiç dökmemesi', 'Meyvelerinden bol miktarda yemeklik yağ elde edilmesi'], 'Kavaklar su kenarlarında hızla büyür ve birkaç on yıl içinde kesime gelir; yumuşak, açık renkli odunu sanayi için elverişlidir.'),
  ('Kanada\'nın bayrağında yer alan ve özsuyundan şurup elde edilen ağaç cinsi hangisidir?', 'Akçaağaç', ['Kayın', 'Huş', 'Dişbudak ya da ıhlamur'], 'Şeker akçaağacının (Acer saccharum) ilkbaharda akan özsuyu kaynatılarak akçaağaç şurubu yapılır; yaprağı Kanada\'nın simgesidir.'),
  ('Kuzey ormanlarında yetişen, beyaz ve kâğıt gibi soyulan kabuğuyla tanınan ağaç hangisidir?', 'Huş', ['Gürgen', 'Karaağaç', 'Ceviz'], 'Huş (Betula) ağaçlarının beyaz kabuğu betulin adlı maddeden gelir; kabuk ince tabakalar hâlinde soyulabilir.'),
  ('Dut ağaçlarının Anadolu\'da tarih boyunca ipekçilikle birlikte anılmasının nedeni nedir?', 'İpek böceği tırtıllarının dut yapraklarıyla beslenmesi', ['Dut kabuğundan ipek iplik yapılması', 'Dut meyvesinin ipeği boyaması', 'Dut odununun dokuma tezgâhı için tek malzeme olması'], 'İpek böceği tırtılları neredeyse yalnızca dut, özellikle ak dut yaprağı yer; bu nedenle Bursa gibi ipek merkezlerinde dut bahçeleri kurulmuştur.'),
  ('Biyolojide \'endemik tür\' ne anlama gelir?', 'Yalnızca belirli bir coğrafi bölgede doğal olarak yaşayan tür', ['Dünyanın hemen her yerinde yaşayabilen tür', 'İnsanlar tarafından başka kıtadan getirilen tür', 'Neslinin tükendiği kesin olarak bilinen tür'], 'Endemik tür, doğal yayılışı belli bir bölge, ülke, dağ ya da adayla sınırlı olan türdür.'),
  ('Dünyanın birçok bölgesinde doğal olarak bulunabilen, geniş yayılışlı türler için kullanılan terim hangisidir?', 'Kozmopolit', ['Endemik', 'Relikt', 'Egzotik ve yabancı'], 'Kozmopolit türler birçok kıtada ve farklı iklimlerde bulunabilir; endemik türlerin karşıtı olarak düşünülebilir.'),
  ('Bir ülkedeki endemik türlerin oranını genellikle yükselten etkenlerden biri hangisidir?', 'Engebeli ve çeşitli bir yüzey şekli', ['Tamamen düz ve tek tip bir arazi', 'Her yerde aynı iklimin görülmesi', 'Çevre ülkelerle sürekli bağlantılı düz ovalar'], 'Dağlar, vadiler ve farklı toprak tipleri toplulukları birbirinden yalıtır ve farklı yaşam koşulları oluşturur; bu da yeni türlerin ortaya çıkmasını kolaylaştırır.'),
  ('Karadeniz kıyılarındaki nemli ve geniş yapraklı ormanlar Türkiye\'nin hangi fitocoğrafik bölgesi içinde yer alır?', 'Avrupa-Sibirya', ['İran-Turan', 'Akdeniz', 'Sahra-Arabistan'], 'Avrupa-Sibirya bölgesi bol yağışlı ve serin iklimle karakterize olur; kayın, kızılağaç ve ladin gibi türler bu bölgeye özgüdür.'),
  ('İç Anadolu\'nun yazları kurak, kışları soğuk bozkırları Türkiye\'nin hangi fitocoğrafik bölgesine girer?', 'İran-Turan', ['Avrupa-Sibirya', 'Akdeniz', 'Hirkan-Öksin'], 'İran-Turan bölgesi karasal iklimin hâkim olduğu, geven ve yavşan gibi bozkır bitkilerinin yaygın olduğu bölgedir.'),
  ('Dar bir alanda yaşayan endemik bitkilerin neslinin tükenme riski genellikle neden daha yüksektir?', 'Tek bir alanın tahribi türün tamamını yok edebilir', ['Endemik bitkiler hiç tohum üretmez', 'Endemik bitkiler yalnızca gece büyür', 'Endemik bitkilerin kökleri yoktur ve sudan beslenirler'], 'Yayılışı küçük olan türlerin tüm bireyleri birkaç noktada toplanır; bir baraj, maden ya da yangın bu noktaları yok ederse tür tamamen kaybolabilir.'),
  ('Kar erimeye başlarken çiçek açan, beyaz sarkık çiçekleriyle tanınan ve Türkiye\'den yasal kotalarla soğanları ihraç edilen bitki cinsi hangisidir?', 'Kardelen (Galanthus)', ['Lale (Tulipa)', 'Ters lale (Fritillaria)', 'Çiğdem (Crocus)'], 'Kardelen soğanlarının doğadan toplanıp satılması uluslararası ticareti düzenleyen CITES kapsamında denetlenir; Türkiye bu ticarette önemli bir ülkedir.'),
  ('Soğan, yumru ya da rizom gibi toprak altı organlarında besin depolayarak olumsuz mevsimi toprak altında geçiren bitkilere ne ad verilir?', 'Geofit', ['Epifit', 'Halofit', 'Hidrofit'], 'Geofitler kurak yaz ya da soğuk kış dönemini toprak altındaki organlarında geçirir; Türkiye lale, çiğdem ve kardelen gibi geofitler bakımından çok zengindir.'),
  ('Lale cinsinin dünyadaki önemli çeşitlilik merkezlerinden biri Orta Asya ve Anadolu\'dur. Osmanlı döneminde laleye verilen önem hangi dönem adıyla da hatırlanır?', 'Lale Devri', ['Gül Devri', 'Sümbül Çağı', 'Karanfil Dönemi'], '18. yüzyılın başında III. Ahmed döneminde lale yetiştiriciliği ve lale merakı öyle yaygınlaştı ki dönem Lale Devri olarak anılır.'),
  ('Safranbolu ilçesinin adı, eskiden çevresinde yoğun olarak yetiştirilen hangi bitkiden gelir?', 'Crocus sativus (safran çiğdemi)', ['Papaver somniferum (haşhaş)', 'Cannabis sativa (kenevir)', 'Gossypium hirsutum (pamuk)'], 'Safranbolu adı, bölgede tarih boyunca safran yetiştirilmesiyle ilişkilendirilir; ilçe çevresinde safran üretimi bugün de sürdürülmektedir.'),
  ('Türkiye\'nin doğasında yetişen bazı orkidelerin yumruları kurutulup öğütülerek salep yapılır. Bu uygulama orkideler için neden ciddi bir tehdit oluşturur?', 'Yumru alınınca bitkinin kendisi yok olur', ['Orkidelerin yalnızca yaprakları kullanılır', 'Orkideler her yıl yeniden ekilir', 'Salep yapımı yalnızca tohumla yapılır'], 'Salep için bitkinin toprak altındaki yumrusu sökülür; bu, bireyin ölmesi demektir. Aşırı toplama yabani orkide topluluklarını hızla azaltır.'),
  ('Nesli tehlikedeki bir bitkinin tohumlarının bir gen bankasında düşük sıcaklıkta saklanması hangi koruma yaklaşımına örnektir?', 'Yer dışında (ex situ) koruma', ['Yerinde (in situ) koruma', 'Biyolojik mücadele', 'Ağaçlandırma ve fidan dikme yöntemi'], 'Ex situ koruma türü doğal ortamı dışında, tohum bankası, botanik bahçesi veya doku kültürüyle korur; doğal popülasyon kaybolsa bile yeniden üretim olanağı sağlar.'),
  ('Dünyanın dört bir yanındaki gen bankalarından tohum kopyalarının yedek olarak saklandığı, Kuzey Kutbu\'na yakın bir adada donmuş toprak içine oyulmuş tesis hangisidir?', 'Svalbard Küresel Tohum Kasası', ['Türkiye Tohum Gen Bankası', 'Kew Bahçeleri Herbaryumu', 'Nezahat Gökyiğit Botanik Bahçesi'], 'Norveç\'in Svalbard takımadalarındaki bu kasa, savaş ya da doğal afet gibi durumlarda kaybolabilecek tohumlar için küresel bir yedek deposu işlevi görür.'),
  ('Kurutulup preslenmiş bitki örneklerinin bilimsel amaçla etiketlenerek saklandığı koleksiyonlara ne ad verilir?', 'Herbaryum', ['Akvaryum', 'Terraryum', 'Arboretum ya da fidanlık'], 'Herbaryumlar türlerin tanımlanması, yayılışlarının belgelenmesi ve sınıflandırma çalışmaları için temel kaynaktır. Arboretum ise canlı ağaç koleksiyonudur.'),
  ('Aspirinin etkin maddesi olan asetilsalisilik asidin geliştirilmesine, eski çağlardan beri ağrı ve ateşe karşı kabuğu kullanılan hangi ağaçtaki doğal bileşik öncülük etmiştir?', 'Söğüt', ['Çam', 'Ceviz', 'Ihlamur'], 'Söğüt kabuğundaki salisin vücutta salisilik aside dönüşür; 19. yüzyılda bundan yola çıkılarak daha az mide tahriş eden asetilsalisilik asit üretilmiştir.'),
  ('Bitkilerden elde edilen bir maddenin ilaç ya da zehir olması çoğu zaman neye bağlıdır?', 'Alınan miktara, yani doza', ['Bitkinin yetiştiği ülkeye', 'Maddenin rengine', 'Bitkinin çiçek açtığı mevsime'], 'Paracelsus\'un \'zehri ilaçtan ayıran dozdur\' sözü, yüksük otu gibi bitkiler için açıkça geçerlidir; aynı madde küçük dozda tedavi eder, büyük dozda öldürür.'),
  ('Defne (Laurus nobilis) yaprağı yemeklere tat vermek için kullanılır. Hatay yöresinde bu bitkinin meyvesinden elde edilen yağla yapılan geleneksel ürün hangisidir?', 'Defne sabunu', ['Pekmez', 'Tahin', 'Zeytinyağlı reçel'], 'Defne meyvelerinden çıkarılan yağ zeytinyağıyla karıştırılarak Antakya\'nın ünlü defne sabunları yapılır.'),
  ('Sumak bitkisinin kurutulup öğütülen meyveleri mutfakta hangi amaçla kullanılır?', 'Yemeklere ekşi bir tat vermek', ['Hamuru mayalamak', 'Etleri tatlandırmak için şeker yerine', 'Yemekleri koyulaştırmak için nişasta yerine'], 'Sumak (Rhus coriaria) meyveleri organik asitler bakımından zengindir; salata ve kebaplara ekşi ve kırmızımsı bir tat katar.'),
  ('Çay bitkisinin (Camellia sinensis) Türkiye\'de büyük ölçüde Doğu Karadeniz\'de yetiştirilmesinin başlıca nedeni nedir?', 'Bol yağışlı ve ılıman iklimle asidik topraklar', ['Kurak ve tuzlu bozkır toprakları', 'Sürekli donlu ve karlı kışlar', 'Çöl iklimi ve kumlu topraklar'], 'Çay bitkisi her mevsim yağışlı, ılıman iklimi ve asidik toprakları sever; Rize ve çevresi bu koşulları en iyi sağlayan bölgedir.'),
  ('Kına bitkisinin (Lawsonia inermis) yaprakları kurutulup öğütüldükten sonra hangi amaçla kullanılır?', 'Saç, el ve kumaş boyamak', ['Yemeklere ekşi tat vermek', 'Ağrı kesici ilaç yapmak', 'Ekmek mayalamak'], 'Kına yapraklarındaki lawson adlı boya maddesi deri ve saçtaki proteinlere bağlanarak turuncu-kırmızı renk verir.'),
  ('Şeker pancarı ile şeker kamışından elde edilen sofra şekeri kimyasal olarak aynı maddedir. Bu madde hangisidir?', 'Sakaroz', ['Glikoz', 'Laktoz', 'Nişasta ve selüloz'], 'Her iki bitkiden de elde edilen şeker sakarozdur; pancarda kökte, şeker kamışında gövdede depolanır.'),
  ('Mantar, kağıt, kereste, reçine ve tanen gibi ürünlerin hepsinin ortak kaynağı aşağıdakilerden hangisidir?', 'Orman ağaçları', ['Tahıl tarlaları', 'Deniz algleri', 'Çöl kaktüsleri'], 'Bu ürünlerin tümü ağaçlardan elde edilir: mantar mantar meşesinden, reçine kozalaklılardan, tanen meşe ve kestane gibi ağaçlardan.'),
  ('Buğday, arpa, mercimek ve nohut gibi bitkilerin ilk kez kültüre alındığı bölgelerden biri olan, Güneydoğu Anadolu\'yu da içine alan yay biçimli alana ne ad verilir?', 'Bereketli Hilal', ['Anadolu Çaprazı', 'İpek Yolu', 'Altın Üçgen bölgesi'], 'Bereketli Hilal Mezopotamya\'dan Levant\'a uzanır; tarımın yaklaşık 10-11 bin yıl önce başladığı ilk merkezlerdendir.'),
  ('Bir öğrenci domates, patates, mısır ve biberin Osmanlı mutfağına ancak 16. yüzyıldan sonra girdiğini okuyor. Bunun en doğru açıklaması nedir?', 'Bu bitkilerin anavatanı Amerika kıtasıdır', ['Bu bitkiler o tarihe kadar zehirli sanılıp hiç tanınmıyordu', 'Bu bitkiler ancak Orta Asya\'dan getirilebildi', 'Bu bitkiler yalnızca seralarda yetişebiliyordu'], 'Bu kültür bitkileri Amerika\'da evcilleştirilmiştir; Kristof Kolomb\'un yolculuklarından sonra Avrupa, Afrika ve Asya\'ya yayılmışlardır.'),
  ('Patatesin anavatanı olan bölge hangisidir?', 'Güney Amerika\'daki And Dağları', ['Orta Avrupa ovaları', 'Doğu Afrika yaylaları', 'Güneydoğu Asya\'daki tropikal adalar'], 'Patates bugünkü Peru ve Bolivya çevresinde And Dağları\'nda evcilleştirilmiş, 16. yüzyılda Avrupa\'ya taşınmıştır.'),
  ('Bitkiler için yerel adlar yerine Latince bilimsel adların kullanılmasının en önemli yararı nedir?', 'Her türün dünya genelinde tek ve ortak bir adının olması', ['Bilimsel adların daha kısa olması', 'Bilimsel adların bitkinin rengini göstermesi', 'Yerel adların her zaman yanlış olması'], 'Aynı bitkiye farklı yörelerde farklı adlar verilebilir ya da aynı ad farklı bitkiler için kullanılabilir; bilimsel ad bu karışıklığı ortadan kaldırır.'),
  ('Gregor Mendel kalıtım yasalarını keşfettiği deneylerinde hangi bitkiyi kullanmıştır?', 'Bezelye', ['Mısır', 'Buğday', 'Fasulye ve nohut'], 'Mendel bezelyede tohum rengi ve biçimi gibi kolayca ayırt edilen özelliklerin kuşaklar boyunca aktarılışını inceleyerek kalıtımın temel ilkelerini ortaya koymuştur.'),
  ('Zeytinin kültüre alındığı ve en eski zeytin yetiştiriciliğinin görüldüğü bölge için hangisi doğrudur?', 'Doğu Akdeniz çevresi', ['Kuzey Avrupa', 'Orta Afrika', 'Güney Amerika\'nın And Dağları'], 'Zeytin Doğu Akdeniz\'de, Levant ve Anadolu\'yu içine alan bölgede binlerce yıl önce kültüre alınmıştır.'),
  ('Kesilmiş bir ağaç kütüğünde 48 tane yıllık halka sayılıyor. Ilıman bir bölgede yetişen bu ağacın yaşı için en iyi tahmin hangisidir?', 'Yaklaşık 48 yıl', ['Yaklaşık 24 yıl', 'Yaklaşık 96 yıl', 'Yaklaşık 12 yıl'], 'Ilıman bölgelerde kambiyum her yıl bir açık ve bir koyu bant ekler; bu ikisi birlikte tek bir yıllık halka sayılır, bu yüzden halka sayısı yaşı verir.'),
  ('Bir ağaç kesitinde bazı yıllık halkaların diğerlerinden çok daha dar olduğu görülüyor. Bu dar halkalar en büyük olasılıkla neyi gösterir?', 'O yıllarda büyümeyi kısıtlayan kuraklık gibi olumsuz koşulları', ['O yıllarda ağacın iki kez çiçek açtığını', 'O yıllarda ağacın daha çok yağış aldığını', 'O yıllarda ağacın hiç yaprak oluşturmadığını'], 'Halka genişliği o yılki büyüme koşullarını yansıtır; kurak, soğuk ya da zararlı saldırısına uğranan yıllarda halkalar dar olur.'),
  ('Yağmur ormanlarında en üstte, tepe örtüsünün de üzerine yükselen tek tük dev ağaçların oluşturduğu katmana ne ad verilir?', 'Yükselen ağaçlar katmanı', ['Orman tabanı', 'Alt çalı katmanı', 'Ot ve eğrelti katmanı'], 'Yağmur ormanları genellikle yükselen ağaçlar, tepe örtüsü (kanopi), alt katman ve orman tabanı olmak üzere katmanlara ayrılır.'),
  ('Tropikal yağmur ormanlarının tabanında genellikle çok az otsu bitki bulunur. Bunun başlıca nedeni nedir?', 'Sık tepe örtüsünün ışığın çok azını tabana geçirmesi', ['Toprağın sürekli donmuş olması', 'Yağışın tabana hiç ulaşmaması', 'Bu ormanlarda hiç böcek bulunmaması'], 'Üst katmanlardaki yoğun yapraklar gelen ışığın büyük bölümünü tutar; orman tabanına ancak küçük bir kısmı ulaşır, bu yüzden otsu bitki az olur.'),
  ('Rusya, Kanada ve İskandinavya\'nın kuzeyinde geniş alanlar kaplayan ve büyük ölçüde iğne yapraklı ağaçlardan oluşan orman kuşağının adı nedir?', 'Tayga', ['Savan', 'Maki', 'Pampa ya da step'], 'Tayga (boreal orman) uzun ve çok soğuk kışlara dayanıklı ladin, köknar, çam ve melez ağaçlarından oluşur; dünyanın en geniş orman kuşağıdır.'),
  ('Akdeniz ikliminin etkili olduğu kıyılarda ormanların tahrip edildiği yerlerde gelişen, kocayemiş, mersin, sakız ve katran ardıcı gibi herdem yeşil çalılardan oluşan bitki örtüsüne ne ad verilir?', 'Maki', ['Tayga', 'Tundra', 'Savan'], 'Maki sert yapraklı, kuraklığa dayanıklı herdem yeşil çalılardan oluşur; daha da bozulduğunda yerini kısa boylu ve seyrek garig topluluklarına bırakır.'),
  ('Ilıman kuşakta yazları yeşil, kışları yapraksız olan kayın, meşe ve akçaağaç ormanları nasıl adlandırılır?', 'Yaprak döken geniş yapraklı ormanlar', ['Herdem yeşil yağmur ormanları', 'Boreal iğne yapraklı ormanlar', 'Mangrov ormanları'], 'Ilıman yaprak döken ormanlar belirgin dört mevsimin yaşandığı bölgelerde bulunur; ağaçlar kışı yapraksız geçirir.'),
  ('Mangrov ormanları hangi ortamlarda gelişir?', 'Tropikal kıyılarda gelgit etkisindeki tuzlu çamurlarda', ['Yüksek dağların alpin çayırlarında', 'Çöllerin iç kesimlerindeki kumullarda', 'Kutup bölgelerindeki donmuş topraklarda'], 'Mangrov ağaçları tuzlu suya ve oksijensiz çamura uyum sağlamış özel köklere sahiptir; tropikal ve astropikal kıyılarda yetişir.'),
  ('İç Anadolu\'nun büyük bölümünde doğal ormanların az olup bozkırın yaygın olmasının temel nedeni nedir?', 'Yağışın az ve yazların kurak olması', ['Toprağın tamamen kumdan oluşması', 'Bölgenin deniz seviyesinin altında olması', 'Kışların çok ılık geçmesi'], 'Dağlarla çevrili iç bölge, nemli rüzgârlardan korunduğu için az yağış alır; ağaçlar ancak daha yüksek ve nemli dağ yamaçlarında yaşayabilir.'),
  ('Bir dağda belirli bir yükseltinin üzerinde ağaçların yetişemediği sınıra ne ad verilir?', 'Orman üst sınırı', ['Kar alt sınırı', 'Tuz sınırı', 'Ekvator çizgisi ve dönence'], 'Orman üst sınırının üstünde düşük sıcaklık, kısa büyüme mevsimi ve rüzgâr ağaç büyümesini engeller; burada alpin çayırlar ve bodur çalılar bulunur.'),
  ('Doğu Karadeniz\'de deniz kıyısından itibaren yükseldikçe yaygın olarak görülen alpin kuşak bitki örtüsünün özelliği nedir?', 'Orman sınırının üstündeki ağaçsız çayırlar', ['Kızılçam ve maki toplulukları', 'Tropikal yağmur ormanları', 'Kumullarda ve tuzlu bataklıklarda yetişen bitkiler'], 'Orman sınırının üstünde yaz boyunca otlarla kaplanan ağaçsız çayırlar yer alır; bu alanlar yayla hayvancılığında kullanılır.'),
  ('Kızılçam ormanlarının Türkiye\'de özellikle Akdeniz ve Ege kıyılarında yayılmasının nedenlerinden biri hangisidir?', 'Sıcak, kurak yazlara ve fakir topraklara dayanıklı olması', ['Bol yağışlı ve serin iklim istemesi', 'Yalnızca bataklık topraklarda yaşayabilmesi', 'Uzun ve karlı kışlara ihtiyaç duyması'], 'Kızılçam Akdeniz ikliminin kuraklığına, yüksek sıcaklıklarına ve sığ, kayalık topraklara uyum sağlamış bir türdür.'),
  ('Bir öğrenci ışığın fotosenteze etkisini incelemek için iki özdeş saksı bitkisinden birini aydınlık, diğerini karanlık bir yere koyuyor. Deneyin geçerli olması için iki saksıda aşağıdakilerden hangisinin farklı olması gerekir?', 'Yalnızca ışık koşulu', ['Su miktarı ve toprak türü', 'Bitki türü ve saksı büyüklüğü', 'Sıcaklık ve gübre miktarı'], 'Kontrollü bir deneyde yalnızca incelenen değişken değiştirilir; diğer tüm koşullar sabit tutulur ki sonuç ışığa bağlanabilsin.'),
  ('Bir akvaryumdaki su bitkisinin yapraklarından ışık altında kabarcıklar çıktığı görülüyor. Lamba bitkiye yaklaştırıldığında kabarcık sayısı artıyor. Bu gözlemden çıkarılabilecek en doğru sonuç hangisidir?', 'Işık şiddeti arttıkça fotosentez hızlanmıştır', ['Bitki ışıkta solunumu tamamen durdurmuştur', 'Lamba suyu kaynatarak kabarcık oluşturmuştur', 'Bitki ışıkta karbondioksit üretmeye başlamıştır'], 'Kabarcıklar büyük ölçüde fotosentezle açığa çıkan oksijendir; ışık yaklaştıkça artması fotosentez hızının ışık şiddetine bağlı olduğunu gösterir.'),
  ('Yaz gecelerinde bir odada çok sayıda saksı bitkisi bulundurulduğunda gece boyunca bitkiler için hangisi doğrudur?', 'Fotosentez yapmaz, yalnızca solunum yaparlar', ['Karanlıkta fotosentez hızlanır', 'Hem fotosentezi hem solunumu durdururlar', 'Geceleri yalnızca oksijen üretirler'], 'Fotosentez ışık gerektirir; karanlıkta bitkiler yalnızca solunum yapar, yani oksijen tüketip karbondioksit verir. Ancak bu miktar bir insanın solunumuna göre çok küçüktür.'),
  ('Bitkiler ürettikleri glikozun bir kısmını hemen kullanmaz. Glikoz fazlası bitkide çoğunlukla hangi biçimde depolanır?', 'Nişasta', ['Glikojen', 'Kitin', 'Kolesterol'], 'Bitkiler fazla glikozu suda çözünmeyen nişasta olarak depolar; hayvanlar ve mantarlar ise glikojen depolar.'),
  ('Beyaz bir karanfilin sapı mavi mürekkepli suya konduğunda birkaç saat sonra taç yaprakları mavileşiyor. Bu deney bitkilerle ilgili neyi gösterir?', 'Suyun gövde boyunca yukarı taşındığını', ['Çiçeğin kendi rengini değiştirebildiğini', 'Fotosentezin taç yapraklarda olduğunu', 'Floemin suyu aşağıya taşıdığını'], 'Boyalı su ksilem boyunca yukarı çıkar ve terlemeyle suyun kaybedildiği taç yapraklara ulaşır; boya orada birikerek rengi değiştirir.'),
  ('Bir fidanı başka bir yere taşırken köklerin etrafındaki toprak kütlesini bozmadan taşımak neden önerilir?', 'İnce kök tüylerinin kopmasını önlemek', ['Toprağın fidanı soğuktan koruması', 'Fidanın daha çabuk çiçek açması', 'Toprağın fidana oksijen sağlaması'], 'Su ve mineral alımının çoğunu yapan kök tüyleri çok incedir ve toprak dağıtılınca kolayca kopar; bu da fidanın solmasına yol açar.'),
  ('Fazla sulanan ve suyun hiç süzülemediği saksılarda bitki köklerinin çürümesinin temel nedeni nedir?', 'Topraktaki hava boşlukları dolunca köklerin oksijensiz kalması', ['Suyun köklerdeki klorofili parçalaması', 'Köklerin fazla ışık alması', 'Suyun toprağı tuzlu hâle getirmesi'], 'Kök hücreleri solunum için oksijene ihtiyaç duyar; toprağın gözenekleri tamamen suyla dolarsa kökler boğulur ve çürüme etkenlerine açık hâle gelir.'),
  ('Dünya genelindeki ormanların atmosferdeki karbondioksit düzeyini etkilemesinin temel nedeni nedir?', 'Ağaçların fotosentezle karbonu odunlarında biriktirmesi', ['Ağaçların gece boyunca karbondioksit yakması', 'Ormanların atmosferdeki azotu karbondioksite çevirmesi', 'Ağaç köklerinin karbondioksiti toprağa pompalaması'], 'Ağaçlar fotosentezle aldıkları karbonu selüloz ve lignin olarak uzun yıllar gövde, dal ve köklerinde tutar; bu nedenle ormanlar önemli karbon depolarıdır.'),
  ('Bir meyve bahçesine arı kovanları getirilmesinin, kiraz ve elma gibi ağaçlarda ürün miktarını artırmasının nedeni nedir?', 'Arıların tozlaşmayı artırması', ['Arıların toprağa azot bırakması', 'Arıların zararlı mantarları yemesi', 'Arıların ağaçları soğuktan koruması'], 'Bu meyve ağaçlarının çoğu böceklerle tozlaşır ve bazı çeşitler kendine uyuşmazdır; arılar polenleri çiçekler arasında taşıyarak meyve bağlamayı artırır.'),
  ('Bir tohumun içindeki embriyonun ilk gelişen ve toprağa doğru uzanan kısmı hangisidir?', 'Kökçük', ['Sürgüncük', 'Çenek', 'Tohum kabuğu'], 'Çimlenmede genellikle önce kökçük (radikula) tohum kabuğunu yırtarak çıkar; böylece fide hızla su almaya başlar.'),
  ('Çimlenmenin ilk aşamasında, henüz yaprak oluşmadan önce fidenin enerji kaynağı nedir?', 'Tohumda depolanmış besinler', ['Yapraklarda yapılan fotosentez', 'Havadan alınan azot', 'Toprağın ısısı'], 'Fide fotosentez yapacak yaprakları açana kadar çenek veya endospermde depolanmış nişasta, yağ ve proteinleri kullanır.'),
  ('Isparta yöresinde parfüm ve kozmetik sanayi için yağı elde edilmek üzere geniş alanlarda yetiştirilen gül türü hangisidir?', 'Yağ gülü (Rosa damascena)', ['Kuşburnu (Rosa canina)', 'Sarmaşık gülü (Rosa multiflora)', 'Çin gülü (Rosa chinensis) ve melezleri'], 'Isparta gülü olarak da bilinen Rosa damascena\'nın taze taç yapraklarından damıtmayla gül yağı ve gül suyu elde edilir.'),
  ('Bir kardelen soğanı sonbaharda toprağa dikilmiş ve ilkbaharda çiçek açmıştır. Çiçeklenme için gereken enerji büyük ölçüde nereden gelmiştir?', 'Soğanın etli yapraklarında depolanan besinden', ['Çiçeğin taç yapraklarındaki fotosentezden', 'Topraktaki kardan', 'Toprak bakterilerinin ürettiği şekerden'], 'Soğanlı bitkiler bir önceki yıl ürettikleri besinleri soğanlarında depolar; bu besinler ertesi ilkbaharda hızlı büyüme ve çiçeklenme için kullanılır.'),
  ('Bir lale soğanının çiçeklendikten hemen sonra yapraklarının kesilmesi önerilmez. Bunun nedeni nedir?', 'Yaprakların ertesi yıl için soğana besin depolaması', ['Yaprakların çiçeği yeniden açması', 'Yaprakların soğanı dondan koruması', 'Yaprakların tohumları doğrudan toprağa ekmesi'], 'Çiçeklenme sonrasında yapraklar fotosentezle besin üretip soğana taşır; erken kesilirse soğan zayıflar ve ertesi yıl çiçek vermeyebilir.'),
  ('Doğadan çiçek ya da soğan sökmek yerine fotoğraf çekmeyi tercih eden bir doğa yürüyüşçüsü hangi ilkeye uygun davranmış olur?', 'Doğal yaşam alanındaki bitkilere zarar vermemek', ['Bitkileri kendi bahçesine taşımak', 'Nadir bitkileri koleksiyona katmak', 'Bitkileri başka yörelere yaymak'], 'Doğadaki bitkiler, özellikle nadir ve endemik türler, sökülmeden yerinde bırakıldığında üremeye ve topluluklarını sürdürmeye devam eder.'),
  ('Türkiye\'de bazı yabani bitkilerin soğan ve yumrularının doğadan toplanması ve ihracatı yasal düzenlemelerle kotaya bağlanmıştır. Bu düzenlemenin temel amacı nedir?', 'Doğal toplulukların aşırı toplamayla tükenmesini önlemek', ['Bu bitkilerin yurt dışında yetişmesini engellemek', 'Bitkilerin fiyatlarını düşürmek', 'Bitkilerin hiç çiçek açmamasını sağlamak'], 'Kontrolsüz toplama doğal toplulukları hızla azaltır; kota ve izin sistemi toplanabilecek miktarı sınırlayarak türlerin sürdürülebilir kullanımını hedefler.'),
  ('İnsanlar tarafından başka bir bölgeden getirilip yeni yerinde hızla yayılarak yerli bitkilerin yerini alan türlere ne ad verilir?', 'İstilacı yabancı tür', ['Endemik tür', 'Relikt tür', 'Yerli tür'], 'İstilacı türler doğal düşmanlarından uzakta hızla çoğalır; yerli ve endemik bitkilerle rekabet ederek onları tehdit edebilir.'),
  ('Türkiye\'nin Doğu Karadeniz kıyısından Güneydoğu Anadolu\'ya kadar yalnızca birkaç yüz kilometrede çok farklı bitki örtüleri görülmesinin temel nedeni nedir?', 'İklim ve yükseltinin kısa mesafede büyük farklılık göstermesi', ['Bütün bölgelerin aynı yağışı alması', 'Bitkilerin rüzgârla her yıl yer değiştirmesi', 'Türkiye\'nin tamamen düz bir ülke olması'], 'Nemli Karadeniz kıyıları, yüksek dağlar, kurak iç yaylalar ve sıcak güney ovaları arasında kısa mesafede büyük iklim farkları bulunur; bu da bitki örtüsünü çeşitlendirir.'),
  ('Sığırkuyruğu bitkilerinin yaprakları yoğun ve yumuşak tüylerle kaplıdır. Bu tüylerin kurak ve güneşli ortamda bitkiye sağladığı yarar nedir?', 'Yaprak yüzeyini serin tutup su kaybını azaltmak', ['Yaprakları suya batırmak', 'Böcekleri yakalayıp sindirmek', 'Kökleri topraktan çekip çıkarmak'], 'Tüyler güneş ışığının bir kısmını yansıtır ve yaprak yüzeyinde durgun bir hava tabakası tutar; bu da terlemeyi azaltır.'),
  ('Adaçayı, kekik ve lavanta gibi Akdeniz bitkilerinin yapraklarında bulunan uçucu yağların bu bitkilere sağladığı yararlardan biri hangisidir?', 'Otçul hayvanları ve zararlıları uzaklaştırmak', ['Fotosentez yerine enerji üretmek', 'Su altında solunum yapmak', 'Köklerinden azot bağlamak'], 'Uçucu yağlar güçlü koku ve tatlarıyla otçul hayvanlar ve böcekler için caydırıcıdır; bazıları mikrop ve mantarlara karşı da koruyucu etki gösterir.'),
  ('Havuç, turp ve şeker pancarında yediğimiz kısım bitkinin hangi organıdır?', 'Kök', ['Gövde', 'Yaprak', 'Çiçek durumu ve sapı'], 'Bu bitkilerde ana kök besin depolayarak kalınlaşmıştır; yediğimiz kısım değişime uğramış köktür.'),
  ('Brokoli ve karnabaharda yediğimiz kısım bitkinin hangi bölümüdür?', 'Çiçek durumu', ['Kök', 'Tohum', 'Meyve kabuğu ve sapı'], 'Brokoli ve karnabahar henüz açmamış çiçek tomurcuklarından oluşan kalın çiçek durumlarıdır.'),
  ('Fasulye, kabak, salatalık, patlıcan ve biberin ortak botanik özelliği nedir?', 'Tohum taşıyan meyveler olmaları', ['Değişime uğramış kökler olmaları', 'Yaprak sapları olmaları', 'Toprak altında gelişen gövde parçaları olmaları'], 'Bu sebzelerin tümü çiçeğin yumurtalığından gelişir ve içlerinde tohum bulunur; bu yüzden botanik açıdan meyvedir.'),
  ('Kuşburnu bitkisinin meyvesi C vitamini bakımından zengindir. Kuşburnu hangi bitkinin meyvesidir?', 'Yabani gül', ['Yabani elma', 'Mürver', 'Ahududu'], 'Kuşburnu, yabani gül türlerinin (Rosa) yalancı meyvesidir; çay, marmelat ve pekmez yapımında kullanılır.'),
  ('Su kenarında yetişen bir bitkinin meyveleri hafif, hava dolu ve suda yüzebilen yapıda. Bu bitkinin tohumlarını yaymak için en çok hangi yolu kullandığı düşünülür?', 'Su ile taşınma', ['Rüzgârla uçma', 'Kuşların tüylerine yapışma', 'Patlayarak fırlatma'], 'Suda yüzen, hava içeren meyve kabukları su akıntılarıyla taşınmaya uygundur; nilüfer ve hindistan cevizi gibi bitkilerde görülür.'),
  ('Bir bitkinin kökü, gövdesi ve yaprakları arasındaki görev paylaşımı düşünüldüğünde aşağıdaki eşleştirmelerden hangisi doğrudur?', 'Kök: su alımı; yaprak: fotosentez', ['Kök: fotosentez; yaprak: su alımı', 'Gövde: tohum üretimi; kök: fotosentez', 'Yaprak: toprağa tutunma; gövde: polen üretimi'], 'Kökler bitkiyi toprağa bağlar, su ve mineralleri emer; yapraklar ise fotosentezin başlıca yeridir. Gövde taşıma ve destek görevi görür.'),
  ('Bitkilerin toprak yerine besin elementleri eklenmiş su içinde yetiştirilmesi yöntemine ne ad verilir ve bu yöntem bitkilerin topraktan asıl olarak neye ihtiyaç duyduğunu gösterir?', 'Hidroponik; su ve mineral maddeler', ['Aşılama; topraktaki bakteriler', 'Doku kültürü; topraktaki kum', 'Daldırma; topraktaki çakıl taşları'], 'Hidroponik tarım, bitkilerin topraktan esas olarak su ve çözünmüş mineraller aldığını gösterir; toprağın kendisi zorunlu değildir, destek ve depo işlevi görür.'),
  ('Bir bitkiden bir hafta boyunca bütün yapraklar sürekli koparılırsa bitkinin büyümesi en çok hangi nedenle durur?', 'Besin üretimi neredeyse durur', ['Kökler topraktan ayrılır', 'Gövde suyu hiç taşıyamaz', 'Tohumlar hemen çimlenir'], 'Fotosentezin büyük kısmı yapraklarda yapılır; yapraksız kalan bitki yeni şeker üretemez ve depolarını tüketince büyüyemez.'),
  ('Yeşil yapraklı bir bitkinin yaprağında klorofilin bulunduğu organel hangisidir?', 'Kloroplast', ['Mitokondri', 'Çekirdek', 'Lizozom'], 'Klorofil, fotosentezin gerçekleştiği kloroplastların tilakoit zarlarında bulunur.'),
  ('Aşağıdaki canlılardan hangisi kendi besinini fotosentezle üretebilir?', 'Ayçiçeği', ['Şapkalı mantar', 'Küf', 'Maya'], 'Ayçiçeği klorofilli bir bitkidir. Şapkalı mantar, küf ve maya ise mantarlar âlemindendir ve hazır besin kullanır.'),
  ('Bir saksıda yetişen bitkinin yaprakları aynı kalırken kök ucunun her gün biraz daha derine indiği gözleniyor. Bu büyümeyi sağlayan hücre bölünmeleri en çok nerede gerçekleşir?', 'Kök ucundaki meristemde', ['Yaprakların damarlarında', 'Kökün en yaşlı kısmında', 'Gövdenin kabuğunda'], 'Kökün boyca uzaması kök ucunda, kaliptranın hemen arkasındaki meristem bölgesinde gerçekleşen bölünmelerle sağlanır.'),
  ('Buğday ve mısır gibi tahıllarda ana kök belirginleşmez; aynı kalınlıkta çok sayıda ince kök toprağa yayılır. Bu kök tipinin adı nedir?', 'Saçak kök', ['Kazık kök', 'Depo kökü', 'Solunum kökü'], 'Saçak kök sistemi tek çeneklilerde yaygındır; toprağın üst katmanına yayılarak toprağı iyi tutar ve erozyonu azaltır.'),
  ('Eğimli arazilerde toprak kaymasını azaltmak için çim ve otsu bitkilerin ekilmesinin en önemli nedeni nedir?', 'Saçak köklerin toprağı sıkıca tutması', ['Otların toprağı tuzlu hâle getirmesi', 'Çimlerin yağmuru tamamen durdurması', 'Otların toprağı kurutup sertleştirmesi'], 'Yoğun ve ince saçak kökler toprak taneciklerini birbirine bağlar; yaprak örtüsü de yağmur damlalarının çarpma etkisini azaltır.'),
  ('Bir sarmaşık bitkisi (Hedera helix) taş duvara tırmanırken duvara gövdesinden çıkan küçük köklerle tutunur. Bu kökler hangi gruba girer?', 'Tutunma kökleri', ['Kazık kökler', 'Solunum kökleri', 'Depo kökleri'], 'Sarmaşığın gövdesinden çıkan adventif kökler yüzeydeki girintilere yapışarak bitkinin tırmanmasını sağlar.'),
  ('Bir bitki türünün gövdesi yeşil, yumuşak ve bir yıl içinde kuruyor; başka bir türün gövdesi ise kahverengi, sert ve yıllarca yaşıyor. Bu iki gövde tipi nasıl adlandırılır?', 'Otsu ve odunsu gövde', ['Toprak altı ve toprak üstü gövde', 'Rizom ve stolon', 'Sülük ve diken'], 'Otsu gövdeler yumuşak ve yeşildir, genellikle kısa ömürlüdür; odunsu gövdeler ise ikincil büyümeyle kalınlaşıp sertleşir ve uzun yıllar yaşar.'),
  ('Yaprak ayasını yaprak sapına ve gövdeye bağlayan damarların görevi nedir?', 'Su ve besin taşımak, yaprağı desteklemek', ['Polen üretmek', 'Kök tüylerini oluşturmak', 'Böcekleri yakalamak'], 'Yaprak damarları ksilem ve floem içeren iletim demetleridir; suyu yaprağa getirir, şekeri dışarı taşır ve yaprağa iskelet gibi destek verir.'),
  ('Bir bitkinin yapraklarının gövdeye dizilişi her boğumda iki yaprak karşı karşıya gelecek biçimdeyse bu diziliş nasıl adlandırılır?', 'Karşılıklı diziliş', ['Almaşık diziliş', 'Dairesel (çevrel) diziliş', 'Rozet diziliş'], 'Karşılıklı dizilişte her boğumda iki yaprak bulunur ve birbirine karşı durur; nane ve adaçayında görülür.'),
  ('Bir çiçeğin tepeciğine düşen polen tanesinin dişi organın içinden yumurtalığa kadar uzanan bir yapı oluşturmasına ne ad verilir?', 'Polen tüpü oluşumu', ['Kök tüyü oluşumu', 'Stoma açılması', 'Sporangium oluşumu'], 'Polen tanesi tepecikte çimlenir ve dişicik borusu boyunca ilerleyen polen tüpü, spermleri tohum taslağına ulaştırır.'),
  ('Arılar ve çiçekli bitkiler arasındaki ilişki için en doğru ifade hangisidir?', 'İki taraf da yarar sağlar', ['Yalnızca arı yarar sağlar', 'Yalnızca bitki yarar sağlar', 'İki taraf da zarar görür'], 'Arılar çiçeklerden nektar ve polen alarak beslenir; bitkiler ise polenlerinin taşınmasıyla tozlaşır. Bu ilişki karşılıklı yararlı bir ortak yaşamdır.'),
  ('Bir bahçıvan domates fidelerini dikmeden önce birkaç gün boyunca dışarıda, serin havada bekleterek alıştırıyor. Bu uygulamanın amacı nedir?', 'Fidelerin dış koşullara dayanıklılığını artırmak', ['Fidelerin köklerini kesmek', 'Fidelerin çiçek açmasını engellemek', 'Fidelerin yapraklarını döktürmek'], 'Serada yetişen fideler aniden dışarı alınınca sıcaklık, rüzgâr ve güneş stresinden zarar görebilir; kademeli alıştırma onları güçlendirir.'),
  ('Kuru fasulye, nohut ya da buğday tohumları uygun koşullarda uzun süre saklanabilir ve yıllar sonra bile çimlenebilir. Bunu sağlayan durum nedir?', 'Kuru tohumda metabolizmanın çok yavaşlaması', ['Tohumların sürekli fotosentez yapması', 'Tohumların içinde bol su bulunması', 'Tohumların toprakla temas etmesi'], 'Kuru tohumda su miktarı çok düşüktür; enzim etkinliği ve solunum neredeyse durur. Bu dinlenme durumu tohumun canlılığını uzun süre korur.'),
  ('Kuru bir toprağa dikilen fidenin kökleri, toprağın yalnızca bir yanına gömülü ıslak bir süngere doğru büyüyor. Köklerin bu yönelimi nasıl adlandırılır?', 'Hidrotropizma', ['Fototropizma', 'Termonasti', 'Sismonasti ve tigmonasti'], 'Köklerin suya doğru yönelerek büyümesine hidrotropizma denir; bu sayede kökler topraktaki nemli bölgelere ulaşır.'),
  ('Ayçiçeğinin genç başlarının gün boyunca güneşi doğudan batıya izlemesi hangi uyartıya verilen bir tepkidir?', 'Işık', ['Yerçekimi', 'Dokunma', 'Su'], 'Genç ayçiçeği bitkileri gövdenin farklı taraflarındaki büyüme farkıyla güneşi izler; çiçeklenme olgunlaşınca başlar çoğunlukla doğuya dönük kalır.'),
  ('Bir kişi Rize\'den Ankara\'ya giderken yolda ormanların önce yoğun ve nemli, sonra seyrek ve kuru görünümlü olduğunu, en sonunda bozkıra geçildiğini gözlemliyor. Bu değişimi en çok açıklayan etken nedir?', 'Yağışın kıyıdan iç kesimlere doğru azalması', ['Sıcaklığın iç kesimlerde sürekli artması', 'Toprağın iç kesimlerde tuzla kaplı olması', 'İç kesimlerde güneşin daha az doğması'], 'Karadeniz\'den gelen nemli hava kütleleri dağların kuzey yamaçlarına bol yağış bırakır; dağların ardındaki iç kesimler kurak kalır ve orman yerini bozkıra bırakır.'),
  ('Çam ağaçlarının yaprak biçimi göz önüne alındığında aşağıdakilerden hangisi doğrudur?', 'İnce, uzun ve iğne biçimlidir', ['Geniş ve el biçimlidir', 'Yuvarlak ve etlidir', 'Pul gibi küçük ve üst üste dizilidir'], 'Çamların yaprakları dar ve uzun iğnelerdir; kalın kütikulaları ve gömük stomaları su kaybını azaltır.'),
  ('Çam tohumlarındaki ince zar biçimli kanadın işlevi nedir?', 'Rüzgârla uzağa taşınmayı kolaylaştırmak', ['Tohumu suda yüzdürmek', 'Tohumun hayvan tüyüne yapışmasını sağlamak', 'Tohumu dondan korumak'], 'Kanat düşen tohumun dönerek süzülmesini sağlar; böylece tohum ana ağacın gölgesinden uzaklaşabilir.'),
  ('Fıstık çamının çam fıstığı olarak yenen kısmı botanik açıdan nedir?', 'Kozalaktaki iri tohumlar', ['Kozalağın etli kabuğu', 'Ağacın kök yumruları', 'Çiçeklerin polen kümesi'], 'Çam fıstığı, fıstık çamı kozalaklarının pulları arasında gelişen iri ve kanadı körelmiş tohumlardır.'),
  ('Bir bahçede her yıl lale soğanlarının yanında küçük yeni soğancıklar oluştuğu görülüyor. Bu soğancıkların ayrılıp dikilmesiyle elde edilen laleler için hangisi doğrudur?', 'Ana bitkiyle genetik olarak aynıdır', ['Mutlaka farklı renkte çiçek açar', 'Tohumdan gelişmiş bireylerdir', 'Ana bitkiden farklı bir türe aittir'], 'Yavru soğanlar eşeysiz, yani vejetatif üremeyle oluşur; bu nedenle ana bitkinin genetik kopyalarıdır ve aynı çeşit özelliklerini taşır.'),
  ('Bir parkta yaşlı bir çınarın gövdesine sarılmış metal tel yıllar sonra kabuğun içine gömülmüş görünüyor. Bunun nedeni nedir?', 'Gövdenin tel çevresinde kalınlaşmaya devam etmesi', ['Telin zamanla kabuğu eritmesi', 'Ağacın teli kökleriyle çekmesi', 'Telin yağmurla aşağı kayması'], 'Kambiyum her yıl yeni odun ve kabuk üretir; gövde kalınlaştıkça sıkı bağlanmış nesneleri sarıp içine alır. Bu nedenle ağaçlara tel bağlanması önerilmez.'),
  ('Ihlamur, akasya ve kestane çiçeklerinin bal arıları için önemli olmasının nedeni nedir?', 'Bol nektar üretmeleri', ['Çiçeklerinin hiç polen içermemesi', 'Yalnızca gece açmaları', 'Rüzgârla tozlaşmaları'], 'Bu ağaçların çiçekleri bol nektar üretir; arılar bu nektardan ıhlamur, akasya ve kestane balı gibi tek çiçek ağırlıklı ballar yapar.'),
  ('Bir ağacın yapraklarının hepsi kışın döküldüğü hâlde ilkbaharda yeniden yaprak açabilmesini sağlayan yapılar hangileridir?', 'Dallardaki kış tomurcukları', ['Kökteki polen keseleri', 'Gövdedeki reçine kanalları', 'Yere düşen yapraklar'], 'Ağaçlar sonbaharda pullarla korunan tomurcuklar oluşturur; bu tomurcukların içinde ilkbaharda açılacak yaprak ve çiçeklerin taslakları bulunur.'),
  ('Söğüt ve kavak gibi ağaçların çoğunlukla dere ve göl kenarlarında yetişmesi hangi özellikleriyle ilgilidir?', 'Bol su istemeleri ve ıslak topraklara dayanmaları', ['Kuraklığa çok dayanıklı olmaları', 'Tuzlu suyla beslenmeleri', 'Köklerinin hava ile beslenmesi'], 'Söğüt ve kavaklar çok su tüketir ve taşkın dönemlerinde suya batan topraklara dayanabilir; tohumları da nemli çamurda kolay çimlenir.'),
  ('Kestane ağaçlarının meyveleri olgunlaşana kadar dikenli bir kabuk içinde bulunur. Bu dikenli kabuğun en olası işlevi nedir?', 'Olgunlaşmamış tohumları hayvanlara karşı korumak', ['Rüzgârla uçmayı sağlamak', 'Suda yüzmeyi sağlamak', 'Fotosentezi tamamen üstlenmek'], 'Dikenli kupula tohum olgunlaşana kadar hayvanların onu yemesini zorlaştırır; olgunlaşınca açılarak kestaneleri döker.'),
  ('Eğrelti otları ve karayosunları tohum oluşturmaz. Bu bitkiler yeni bireyleri başlıca neyle oluşturur?', 'Sporlarla', ['Tohumlarla', 'Meyvelerle', 'Kozalaklarla'], 'Sporlar tek hücreli üreme hücreleridir; uygun nemli ortamda çimlenerek yeni bir bitki evresi oluştururlar.'),
  ('Bir öğrenci ormanda yaprak altlarında kahverengi noktalar bulunan, tüy gibi bölünmüş yapraklı ve çiçeği olmayan bir bitki görüyor. Bu bitki büyük olasılıkla hangi gruptandır?', 'Eğrelti otları', ['Kozalaklılar', 'Orkideler', 'Buğdaygiller'], 'Yaprak altındaki kahverengi spor kümeleri ve çiçek bulunmaması eğrelti otlarının tipik özellikleridir.'),
  ('Bir bitkinin yaşam döngüsünü bir yıl içinde tamamlayıp tohum bırakarak öldüğü, örneğin buğday ve gelincikte olduğu gibi, bu bitkilere ne ad verilir?', 'Tek yıllık bitkiler', ['Çok yıllık bitkiler', 'İki yıllık bitkiler', 'Herdem yeşil bitkiler'], 'Tek yıllık bitkiler çimlenme, büyüme, çiçeklenme ve tohum verme aşamalarını tek bir büyüme mevsiminde tamamlar.'),
  ('Havuç ilk yıl yalnızca yaprak ve kalın kök oluşturur, ikinci yıl çiçek açıp tohum verdikten sonra ölür. Bu yaşam döngüsü nasıl adlandırılır?', 'İki yıllık', ['Tek yıllık', 'Çok yıllık', 'Efemer'], 'İki yıllık bitkiler ilk yıl besin depolar, ikinci yıl bu depoyu kullanarak çiçeklenir ve tohum verir.'),
  ('Türkiye\'de yaşı, boyutları, tarihî ya da kültürel önemi nedeniyle tescil edilerek koruma altına alınan yaşlı ağaçlara ne ad verilir?', 'Anıt ağaç', ['Kök ağacı', 'Fidan ağacı', 'Aşı ağacı'], 'Anıt ağaçlar doğal varlık olarak tescil edilir; Anadolu\'daki yüzlerce yıllık çınar, sedir, ardıç ve porsuklar bunlara örnektir.'),
  ('Bir tarlada yetişen buğday bitkilerinin yanındaki yabani otlar ayıklanmazsa buğday veriminin düşmesinin en önemli nedeni nedir?', 'Işık, su ve besin için rekabet', ['Yabani otların buğdayı tozlaştırması', 'Yabani otların toprağı azotla zenginleştirmesi', 'Yabani otların buğdayı dondan koruması'], 'Yabani otlar kültür bitkisiyle aynı kaynakları paylaşır; bu rekabet buğdayın aldığı ışık, su ve besini azaltarak verimi düşürür.'),
  ('Ormanda yere düşen yaprakların zamanla çürüyerek toprağa karışması bitkiler için neden önemlidir?', 'Besin elementlerinin toprağa geri dönmesini sağlar', ['Toprağı tamamen tuzlu hâle getirir', 'Ağaçların köklerini yok eder', 'Toprağı geçirimsiz yapar'], 'Yaprak döküntüsü ayrışınca içindeki azot, fosfor ve potasyum gibi elementler toprağa geçer ve yeniden bitkilerin kullanımına sunulur.'),
  ('Fındığın Türkiye\'de en çok Karadeniz kıyı kuşağında yetiştirilmesinin başlıca nedeni hangisidir?', 'Ilıman ve nemli iklim', ['Kurak ve sıcak yaz iklimi', 'Çok soğuk ve karlı kışlar', 'Tuzlu ve kumlu topraklar'], 'Fındık bol yağışlı, ılıman ve nemli iklimi sever; Ordu, Giresun ve Trabzon gibi Karadeniz illeri bu koşulları sağlar.'),
  ('Çukurova\'da pamuk tarımının yaygın olmasının iklimle ilgili nedeni nedir?', 'Uzun, sıcak ve güneşli büyüme mevsimi', ['Yıl boyunca karla kaplı olması', 'Serin ve sisli yazlar', 'Sürekli don olayları'], 'Pamuk sıcağı seven bir bitkidir ve uzun bir büyüme mevsimine ihtiyaç duyar; Çukurova\'nın sıcak yazları ve sulama olanakları bu bitkiye uygundur.'),
  ('Zeytin ağaçlarının Türkiye\'de en çok Ege ve Akdeniz kıyılarında yetişmesinin temel nedeni nedir?', 'Kışların ılık, yazların sıcak ve kurak geçmesi', ['Kışların çok sert ve karlı geçmesi', 'Yıl boyunca bol yağış düşmesi', 'Yazların serin ve yağışlı geçmesi'], 'Zeytin dona karşı duyarlıdır ve Akdeniz iklimine uyum sağlamıştır; kıyı bölgelerinin ılık kışları bu ağacın yetişmesine olanak verir.'),
  ('Malatya\'nın kayısı, Rize\'nin çay, Giresun\'un fındık üretimiyle tanınmasından yola çıkılarak hangi genellemeye ulaşılabilir?', 'Bitkilerin yetiştiği yeri iklim ve toprak koşulları belirler', ['Bütün bitkiler her bölgede aynı verimle yetişir', 'Bitkilerin yetiştiği yer rastgele seçilir', 'Bitkiler yalnızca kentlerde yetiştirilebilir'], 'Her kültür bitkisinin sıcaklık, yağış ve toprak istekleri farklıdır; bu nedenle bazı bölgeler belirli ürünlerde öne çıkar.'),
  ('Doğadan tıbbi bitki toplayan biri, aynı yerden her yıl bitkileri kökleriyle birlikte sökerse birkaç yıl içinde ne olması beklenir?', 'Bitkinin o yerdeki topluluğu azalır ya da yok olur', ['Bitki sayısı her yıl artar', 'Bitkiler daha büyük ve güçlü olur', 'Bitkiler kendiliğinden başka yere taşınır'], 'Kökleriyle sökülen bitkiler yeniden sürgün veremez ve tohum bırakamaz; toplama yenilenme hızını aşarsa topluluk tükenir.'),
  ('Bir ağaç türünün odunu, yaprakları, meyvesi ve gölgesi farklı biçimlerde kullanılabiliyor. Aşağıdakilerden hangisi bir ağacın insanlara sağladığı odun dışı ürünlere örnektir?', 'Ihlamur çiçeğinden çay yapılması', ['Çam kerestesinden masa yapılması', 'Kayın odunundan sandalye yapılması', 'Meşe odununun yakacak olarak kullanılması'], 'Çiçek, meyve, reçine ve yaprak gibi ürünler odun dışı orman ürünleridir; ıhlamur çiçeği buna örnektir.'),
  ('Bir bitkinin tohumunun etrafını saran meyve etli ve tatlıysa, bu durumun bitkinin evrimi açısından en akla yatkın açıklaması nedir?', 'Hayvanları çekip tohumu yaymalarını sağlamak', ['Tohumu güneşten korumak', 'Tohumu suda batırmak', 'Tohumu rüzgâra karşı sabitlemek'], 'Tatlı ve renkli meyveler hayvanlar için bir ödüldür; hayvanlar meyveyi yerken tohumu başka yerlere taşır.'),
  ('Bonsai sanatında bir ağacın yıllarca saksıda küçük boyda tutulabilmesi hangi uygulamalarla sağlanır?', 'Kök ve dalların düzenli budanmasıyla', ['Ağaca sürekli tuzlu su verilmesiyle', 'Ağacın karanlıkta yetiştirilmesiyle', 'Ağacın her yıl yeniden tohumdan üretilmesiyle'], 'Bonsaide küçük saksı kök gelişimini sınırlar; kök ve dal budaması ile tel sarma ağacın büyüklüğünü ve biçimini denetler. Ağacın kendisi genetik olarak cüce değildir.'),
  ('Bir manavda muzların soğuk depolarda yeşil olarak saklanıp satıştan önce kontrollü ortamda sarartılmasının nedeni nedir?', 'Taşıma sırasında bozulmayı önlemek', ['Muzların tadını tamamen değiştirmek', 'Muzların tohumlu hâle gelmesini sağlamak', 'Muzların ağırlığını iki katına çıkarmak'], 'Yeşil muzlar daha dayanıklıdır; düşük sıcaklık olgunlaşmayı yavaşlatır. Satış yerine yakın olgunlaştırma odalarında etilenle sarartılır.'),
  ('Aşağıdakilerden hangisi bir bitkinin endemik olup olmadığını öğrenmek için en güvenilir bilgi kaynağıdır?', 'Bilimsel flora eserleri ve herbaryum kayıtları', ['Bitkinin rengine bakmak', 'Bitkinin boyunu ölçmek', 'Bitkinin kokusunu koklamak'], 'Bir türün yayılış alanı, flora eserlerinde ve herbaryum örneklerinin toplandığı yer bilgilerinde belgelenir; görünüş özellikleri endemizmi göstermez.'),
  ('Rize\'de çay hasadında bitkiden hangi kısım toplanır?', 'Genç sürgün uçlarındaki taze yapraklar', ['Bitkinin kökleri', 'Olgun tohum kapsülleri', 'Gövdenin yaşlı kabuğu'], 'Çay hasadında genellikle sürgün ucundaki tomurcuk ve onu izleyen birkaç genç yaprak toplanır; kaliteli çay bu taze yapraklardan elde edilir.'),
  ('Botanik bahçelerinin endemik ve nadir bitkilerin korunmasındaki rolü için hangisi doğrudur?', 'Canlı koleksiyonlarla türleri yetiştirip halkı bilgilendirirler', ['Doğal yaşam alanlarını tamamen gereksiz kılarlar', 'Yalnızca yabancı süs bitkilerini yetiştirirler', 'Bitkilerin doğada çoğalmasını engellerler'], 'Botanik bahçeleri ex situ koruma, araştırma ve eğitim merkezleridir; türlerin yetiştirme bilgisini geliştirir ve gerektiğinde doğaya geri kazandırma çalışmalarını destekler.'),
  ('Bir bitkinin \'doğaya geri kazandırılması\' çalışmasında gen bankasında saklanan tohumlardan yetiştirilen fideler nereye dikilmelidir?', 'Türün daha önce doğal olarak yaşadığı uygun alanlara', ['Türün hiç bilinmediği başka bir kıtaya', 'Bir kentin ortasındaki saksılara', 'Türün dayanamayacağı en soğuk bölgelere'], 'Geri kazandırmanın amacı türün kendi doğal yaşam alanında yeniden kendi kendini sürdürebilen bir topluluk oluşturmasıdır.'),
  ('Datça hurmasının dar kıyı alanlarındaki topluluklarına yönelik en ciddi tehditlerden biri aşağıdakilerden hangisidir?', 'Kıyılarda yapılaşma ve turizm baskısı', ['Kutup ayılarının yaprakları yemesi', 'Sürekli kar yağışı', 'Okyanus akıntılarının tohumları dondurması'], 'Datça hurması plaj ve dere ağızlarına yakın kıyı alanlarında yetişir; bu alanlar yapılaşma, yol ve turizm tesisleri için yoğun baskı altındadır.'),
  ('Ankara çiğdemi gibi erken açan endemik soğanlı bitkilerin yaşadığı bozkır alanlarının kentleşmeyle konut alanına dönüşmesi, bu türler için hangi sonucu doğurur?', 'Yaşam alanlarının kalıcı olarak kaybolması', ['Daha çok çiçek açmaları', 'Tohumlarının daha hızlı yayılması', 'Başka bitkilerle melezlenip güçlenmeleri'], 'Toprak beton ve asfaltla kaplandığında soğanlar ve tohum bankası yok olur; yaşam alanı kaybı endemik bitkiler için en büyük tehditlerdendir.'),
  ('Türkiye\'de bir türün endemik olup olmadığı belirtilirken bazen \'Anadolu endemiği\' gibi bir ifade kullanılır. Bu ifade neyi anlatır?', 'Türün yalnızca Anadolu\'da doğal olarak yayıldığını', ['Türün yalnızca Avrupa\'da yaşadığını', 'Türün yalnızca seralarda yetiştiğini', 'Türün tüm dünyada bulunduğunu'], 'Endemizm bir ülkeye, bölgeye, dağa ya da adaya göre tanımlanabilir; \'Anadolu endemiği\' türün doğal yayılışının Anadolu ile sınırlı olduğunu belirtir.'),
];
